import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  interpolateColors,
  Easing,
} from '../remotionShim';
// Font Loader (Standard Pattern)
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Sub-Components ---

const PersonIcon: React.FC<{
  color: string;
  opacity: number;
  scale: number;
  x: number;
  y: number;
  size: number;
}> = ({ color, opacity, scale, x, y, size }) => {
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: size,
        height: size,
        transform: `translate(-50%, -50%) scale(${scale})`,
        opacity,
      }}
    >
      <svg viewBox="0 0 100 100" fill={color} style={{ width: "100%", height: "100%" }}>
        {/* Head */}
        <circle cx="50" cy="35" r="20" />
        {/* Shoulders / Body */}
        <path d="M 15 90 Q 50 45 85 90 L 85 100 L 15 100 Z" />
      </svg>
    </div>
  );
};

// --- Schema & Main Component ---



export type TargetAudienceHighlightProps = Record<string, any>;

const TargetAudienceHighlight: React.FC<TargetAudienceHighlightProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 6,
  iconColor = "#9ca3af",
  dimmedIconColor = "#d1d5db",
  highlightColor = "#3b82f6",
  ringColor = "#60a5fa",
  gridDensity = 10,
  scatterAmount = 40,
  selectionRadius = 250,
  iconSize = 50,
}) => {
  useFontLoader([]); // No text, but keeping pattern consistent

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Drivers ---

  // 1. Initial fade in of all icons
  const entranceOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // 2. Selection phase trigger (start highlighting around frame 30)
  const selectionProgress = interpolate(frame, [30, 60], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });

  // 3. Ring animation (spring based, starts a bit later)
  const ringSpring = spring({
    frame: frame - 35,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // --- Grid Generation ---
  
  const icons = useMemo(() => {
    const items = [];
    const seedBase = "audience-scatter";
    
    // Calculate grid spacing
    const stepX = width / (gridDensity + 1);
    const stepY = height / (gridDensity + 1);
    
    for (let r = 0; r < gridDensity; r++) {
      for (let c = 0; c < gridDensity; c++) {
        const seed = `${seedBase}-${r}-${c}`;
        
        // Base position
        const baseX = stepX * (c + 1);
        const baseY = stepY * (r + 1);
        
        // Add randomness
        const offsetX = (random(seed) - 0.5) * scatterAmount * 2;
        const offsetY = (random(seed + "y") - 0.5) * scatterAmount * 2;
        
        const finalX = baseX + offsetX;
        const finalY = baseY + offsetY;
        
        // Calculate distance from center for selection logic
        const dx = finalX - width / 2;
        const dy = finalY - height / 2;
        const distance = Math.sqrt(dx * dx + dy * dy);
        
        // Determine if this icon is in the "Target Group"
        const isTarget = distance < selectionRadius * 0.8; // Slightly smaller than ring for visual breathing room
        
        items.push({
          id: seed,
          x: finalX,
          y: finalY,
          isTarget,
        });
      }
    }
    return items;
  }, [width, height, gridDensity, scatterAmount, selectionRadius]);

  // --- Render ---

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Layer 1: Icons */}
      {icons.map((icon) => {
        // Dynamic properties based on selection state
        
        // Color transition
        const currentIconColor = icon.isTarget
          ? interpolateColors(selectionProgress, [0, 1], [iconColor, highlightColor])
          : interpolateColors(selectionProgress, [0, 1], [iconColor, dimmedIconColor]);
          
        // Opacity logic
        // If not target, fade out significantly. If target, stay full or brighten.
        const targetOpacity = icon.isTarget ? 1 : 0.3;
        const currentOpacity = interpolate(
            selectionProgress, 
            [0, 1], 
            [1, targetOpacity]
        ) * entranceOpacity;

        // Scale logic
        // Targets pop up slightly, non-targets might shrink slightly
        const targetScale = icon.isTarget ? 1.3 : 0.9;
        const currentScale = interpolate(
            selectionProgress,
            [0, 1],
            [1, targetScale]
        );

        return (
          <PersonIcon
            key={icon.id}
            x={icon.x}
            y={icon.y}
            size={iconSize}
            color={currentIconColor}
            opacity={currentOpacity}
            scale={currentScale}
          />
        );
      })}

      {/* Layer 2: Target Ring / Halo */}
      {/* Only render if animation has started to save resources */}
      {frame > 30 && (
        <div
          style={{
            position: "absolute",
            left: width / 2,
            top: height / 2,
            width: selectionRadius * 2,
            height: selectionRadius * 2,
            borderRadius: "50%",
            border: `4px solid ${ringColor}`,
            transform: `translate(-50%, -50%) scale(${ringSpring})`,
            opacity: ringSpring, // Fade in with the spring
            boxShadow: `0 0 40px ${ringColor}40`, // Soft glow
          }}
        />
      )}

      {/* Layer 3: Pulse effect on ring (subtle secondary ring) */}
      {frame > 45 && (
        <div
            style={{
                position: "absolute",
                left: width / 2,
                top: height / 2,
                width: selectionRadius * 2,
                height: selectionRadius * 2,
                borderRadius: "50%",
                border: `2px solid ${ringColor}`,
                transform: `translate(-50%, -50%) scale(${1 + (frame - 45) * 0.005})`,
                opacity: interpolate(frame - 45, [0, 30], [0.5, 0], { extrapolateRight: "clamp" }),
            }}
        />
      )}

    </AbsoluteFill>
  );
};

export default TargetAudienceHighlight;